// lib/surfEngine.js
export function calculateSurfScore({ waveHeight, wavePeriod, windSpeed, tide }) {
    let score = 0;

    // Wave quality
    //if (waveHeight >= 1.2 && waveHeight <= 2.5) score += 40;
    //else if (waveHeight > 2.5) score += 20;
    score += Math.min(40, waveHeight * 20); // 0.5m = 10pts, 1m = 20pts, 2m = 40pts
    // Period quality
    if (wavePeriod >= 10) score += 30;
    else if (wavePeriod >= 7) score += 15;

    // Wind quality
    if (windSpeed < 10) score += 30;
    else if (windSpeed < 20) score += 15;

    // Tide modifier
    score *= tide?.factor ?? 1;

    return Math.min(100, Math.round(score));
}

// Simple surf interpretation
export function surfLabel(score) {
    if (score > 80) return "🔥 Epic";
    if (score > 60) return "👍 Good";
    if (score > 40) return "🌊 Ok";
    return "💨 Poor";
}